import java.util.List;
import java.util.Iterator;
import java.util.Random;

/**
 * A simple model of a Grass.
 * Deers age, move, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Grass extends Plant
{
    // Characteristics shared by all Grass (class variables).

    // The age to which a Grass can live.
    private static final int MAX_SIZE = 50;
    // The maximum grow rate.
    private static final int MAX_GROW_RATE = 20;
    // The likelihood of grass get steppe fire.
    private static final double STEPPE_FIRE_PROBABILITY = 0.02;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    // Individual characteristics (instance fields).

    // The Grass's age.
    private int size;
    // The Grass's steppe fire status
    private boolean steppeFired;

    /**
     * Create a new Grass. A Grass may be created with size
     * 50 or with a random size.
     * 
     * @param randomSize If true, the Grass will have a random size.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(boolean randomSize, Field field, Location location)
    {
        super(field, location);

        if(randomSize) {
            size = rand.nextInt(MAX_SIZE);
        }
        else {
            size = 50;
        }
        steppeFired = false;
    }

    /**
     * This is what the Grass does most of the time - it grows 
     * around. Sometimes it will breed or die of steppeFire. If
     * the grass catches fire, it will also burn the unit adjacent to it 
     * @param step The current step
     * @param weather The current weather.
     */
    public void act(int step, Weather weather)
    {
        if(isAlive()) {
            if(weather == Weather.RAINY) {
                incrementSize();
                steppeFired = false;
            }
            else {
                getSteppeFire();
                if (steppeFire()==true && getLocation() != null) {                
                    Field field = getField();
                    List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
                    Iterator<Location> it = adjacent.iterator();
                    while(it.hasNext()) {
                        Location where = it.next();
                        Object creature = field.getObjectAt(where);
                        if(creature instanceof Grass) {
                            Grass grass = (Grass) creature;
                            grass.getSteppeFire();                        
                        }
                        if(creature instanceof Animal) {
                            Animal animal = (Animal) creature;
                            animal.burn();                        
                        }
                    }

                    decrementSize();                
                }
            }
        }
    }

    /**
     * Increase the size.
     */
    private void incrementSize()
    {
        size = size + rand.nextInt(MAX_GROW_RATE)+20;
        if(size > MAX_SIZE) {
            size = MAX_SIZE;
        }
    }

    /**
     * Decrease the size.
     */
    public void decrementSize()
    {
        size = size -1;
        if(size == 0) {
            setDead();
        }
    }

    /**
     * Grass can become steppe fire.
     */
    private void getSteppeFire()
    {
        if(rand.nextDouble() <= STEPPE_FIRE_PROBABILITY) {
            steppeFired = true;
        }        
    }

    /**
     * Return steppe fire status.
     * @return true if the grass become steppe fire, false otherwise.
     */
    public boolean steppeFire()
    {
        return steppeFired;
    }

    /**
     * Return size status.
     * @return size The current size of the grass.
     */
    public int getSize()
    {
        return size;
    }

}

import java.util.List;
import java.util.Random;

/**
 * A simple model of a mouse.
 * Mice age, move, eat seed, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Mouse extends Animal
{
    // Characteristics shared by all mouses (class variables).

    // The age at which a mouse can start to breed.
    private static final int BREEDING_AGE = 5;
    // The age to which a mouse can live.
    private static final int MAX_AGE = 125;
    // The likelihood of a mouse breeding.
    private static final double BREEDING_PROBABILITY = 0.25;
    // The likelihood of a mouse infect by disease.
    private static final double INFECT_PROBABILITY = 0.01;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 10;
    // The food value of a single mouse. In effect, this is the
    // number of steps a mouse can go.
    private static final int DEFAULT_FOOD_LEVEL = 5;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The food value of a single mouse. 
    private static final int FOOD_VALUE = 5;

    // Individual characteristics (instance fields).    
    // The mouse's age.
    private int age;
    // The mouse's food level, which is increased by eating seed.
    private int foodLevel;
    // The mouse infected by deisease.
    // 0 - not infect, 1-3 degree of infection.
    private int infect;
    // chance of a mice to recover or deteriorate from disease.
    private static final double recover_probability = 0.3 ;
    private static final double deteriorate_probability = 0.15 ;
    /**
     * Create a new mouse. A mouse may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the mouse will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Mouse(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
        }
        else {
            age = 0;
            foodLevel = DEFAULT_FOOD_LEVEL;
        }
    }

    /**
     * This is what the mouse does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * @param newMice A list to return newly born mouse.
     * @param step The current step.
     * @param weather The current weather.
     */
    public void act(List<Animal> newMice, int step, Weather weather)
    {
        incrementAge();
        updateBurnStatus(weather);
        checkInfectLevel();
        if(isAlive()) {
            // Infected mouse will spread the disease to other mouse.
            if (getInfected() != 0){
                forEachAdjacent(Mouse.class, 1, mouse -> {
                    if(mouse.getInfected() == 0) {
                        mouse.infect();
                    }
                });
                diseaseRecover();
            }
            else {
                giveBirth(newMice);    
                infect();
            }

            // Move towards a source of food if found.
            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = freeAdjacentLocation();
            }

            moveToOrDie(newLocation);
        }                    
    }

    /**
     * Increase the age.
     * This could result in the mouse's death.
     */
    private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

    /**
     * Check whether or not this mouse is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newMice A list to return newly born mouse.
     */
    private void giveBirth(List<Animal> newMice)
    {
        addOffspring(newMice, breed(), (field, location) -> new Mouse(false, field, location));
    }

    /**
     * Look for grass adjacent to the current location.
     * Only the first seed (belong to grass) will be located.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        return findAdjacentLocation(Grass.class, 1, grass -> {
            if(grass.isAlive()) {
                foodLevel += 2;
                return true;
            }
            return false;
        });
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        return calculateBirths(age, BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
    }

    /**
     * @return true if the mouse is infected by disease, false otherwise.
     */
    private int getInfected()
    {
        return infect;
    }

    /**
     * A mouse can be infected by disease.
     */
    private void infect()
    {
        if(rand.nextDouble() <= INFECT_PROBABILITY) {
            infect = 1;
        }        
    }
    /**
     * mouse will die from disease when the infect indicator reach 3.
     */
    private void checkInfectLevel()
    {
        if (infect==3){
                setDead();
            }
    }

    /**
     * A mouse can recover or deteriorate from disease
     */
    private void diseaseRecover()
    {
        if(rand.nextDouble() <= deteriorate_probability) {
            infect ++ ;
        }  
        else if (rand.nextDouble() <= recover_probability) {
            infect -- ;
        }  
    }

    /**
     * @return mouse's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single animal.
 *
 * @version 2016.02.29
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals.
    private Object[][] field;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object animal, int row, int col)
    {
        place(animal, new Location(row, col));
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object animal, Location location)
    {
        field[location.getRow()][location.getCol()] = animal;
    }

    /**
     * Return the animal at the given location, if any.
     * @param location Where in the field.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location, 1);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location, 1);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location, int rcoffset)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1 * rcoffset; roffset <= rcoffset; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1 * rcoffset; coffset <= rcoffset; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A simple model of a Deer.
 * Deers age, move, eat grass, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Deer extends Animal
{
    // Characteristics shared by all Deers (class variables).

    // The age at which a Deer can start to breed.
    private static final int BREEDING_AGE = 10;
    // The age to which a Deer can live.
    private static final int MAX_AGE = 175;
    // The likelihood of a Deer breeding.
    private static final double BREEDING_PROBABILITY = 0.10;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 5;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The food value of a single dear. In effect, this is the
    // number of steps it can go.
    private static final int FOOD_VALUE = 50;
    // The default food value of a single deer.
    private static final int DEFAULT_FOOD_LEVEL = 250;

    // Individual characteristics (instance fields).    
    // The Deer's age.
    private int age;
    // The Deer's food level, which is increased by eating grass.
    private int foodLevel;

    /**
     * Create a new Deer. A Deer may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the Deer will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Deer(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
        }
        else {
            age = 0;
            foodLevel = DEFAULT_FOOD_LEVEL;
        }
    }

    /**
     * This is what the Deer does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * @param newDeers A list to return newly born Deers.
     * @param step The current step
     * @param weather The current weather.
     */
    public void act(List<Animal> newDeers, int step, Weather weather)
    {
        incrementAge();
        incrementHunger();
        updateBurnStatus(weather);
        if(isAlive()) {
            giveBirth(newDeers);  

            // Move towards a source of food if found.
            Location newLocation;
            if (weather == Weather.RAINY) {
                newLocation = null;
            }
            else {
                newLocation = findFood();
            }

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = freeAdjacentLocation();
            }

            moveToOrDie(newLocation);
        }
    }

    /**
     * Increase the age.
     * This could result in the Deer's death.
     */
    private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

    /**
     * Check whether or not this Deer is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newDeers A list to return newly born Deers.
     */
    private void giveBirth(List<Animal> newDeers)
    {
        if(hasAdjacentMate(Deer.class, 2)) {
            addOffspring(newDeers, breed(), (field, location) -> new Deer(false, field, location));
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        return calculateBirths(age, BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
    }

    /**
     * Make this deer more hungry. This could result in the deer's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Look for grass adjacent to the current location.
     * Only the first live grass is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        return findAdjacentLocation(Grass.class, 1, grass -> {
            if(grass.isAlive()) {
                if(grass.getSize() > 12 && foodLevel < 30) {
                    grass.decrementSize();
                    foodLevel += 20;
                }
                return true;
            }
            return false;
        });
    }


    /**
     * @return deer's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A graphical view of the simulation grid.
 * The view displays a colored rectangle for each location 
 * representing its contents. It uses a default background color.
 * Colors for each type of species can be defined using the
 * setColor method.
 *
 * @version 2016.02.29
 */
public class SimulatorView extends JFrame
{
    // Colors used for empty locations.
    private static final Color EMPTY_COLOR = Color.white;

    // Color used for objects that have no defined color.
    private static final Color UNKNOWN_COLOR = Color.gray;

    private final String STEP_PREFIX = "Step: ";
    private final String DAYZONE_PREFIX = " Day Zone: ";
    private final String WEATHER_PREFIX = " Weather: ";
    private final String POPULATION_PREFIX = "Population: ";
    private JLabel stepLabel, population, infoLabel;
    private FieldView fieldView;

    // A map for storing colors for participants in the simulation
    private Map<Class<?>, Color> colors;
    // A statistics object computing and storing simulation information
    private FieldStats stats;

    /**
     * Create a view of the given width and height.
     * @param height The simulation's height.
     * @param width  The simulation's width.
     */
    public SimulatorView(int height, int width)
    {
        stats = new FieldStats();
        colors = new LinkedHashMap<>();

        setTitle("Predator/Prey Simulation");
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        infoLabel = new JLabel("  ", JLabel.CENTER);
        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);

        setLocation(60, 50);

        fieldView = new FieldView(height, width);

        Container contents = getContentPane();

        JPanel infoPane = new JPanel(new BorderLayout());
            infoPane.add(stepLabel, BorderLayout.WEST);
            infoPane.add(infoLabel, BorderLayout.CENTER);
        contents.add(infoPane, BorderLayout.NORTH);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(population, BorderLayout.SOUTH);
        pack();
        setVisible(true);
    }

    /**
     * Define a color to be used for a given class of animal.
     * @param animalClass The animal's Class object.
     * @param color The color to be used for the given class.
     */
    public void setColor(Class<?> animalClass, Color color)
    {
        colors.put(animalClass, color);
    }

    /**
     * Display a short information label at the top of the window.
     */
    public void setInfoText(String text)
    {
        infoLabel.setText(text);
    }

    /**
     * @return The color to be used for a given class of animal.
     */
    private Color getColor(Class<?> animalClass)
    {
        Color col = colors.get(animalClass);
        if(col == null) {
            // no color defined for this class
            return UNKNOWN_COLOR;
        }
        else {
            return col;
        }
    }

    /**
     * Show the current status of the field.
     * @param step Which iteration step it is.
     * @param field The field whose status is to be displayed.
     */
    public void showStatus(int step, Field field, Weather weather)
    {
        String dayzone = "";

        if(!isVisible()) {
            setVisible(true);
        }

        switch (step % 4) {
            case 1:
                dayzone = "Morning ";
                break;
            case 2:
                dayzone = "Afternoon ";
                break;
            case 3:
                dayzone = "Evening ";
                break;
            case 0:
                dayzone = "Night ";
                break;                
        }

        stepLabel.setText(STEP_PREFIX + step + DAYZONE_PREFIX + dayzone + WEATHER_PREFIX + weather);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

    /**
     * Determine whether the simulation should continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return stats.isViable(field);
    }

    /**
     * Provide a graphical view of a rectangular field. This is 
     * a nested class (a class defined inside a class) which
     * defines a custom component for the user interface. This
     * component displays the field.
     * This is rather advanced GUI stuff - you can ignore this 
     * for your project if you like.
     */
    private class FieldView extends JPanel
    {
        private final int GRID_VIEW_SCALING_FACTOR = 20;

        private int gridWidth, gridHeight;
        private int xScale, yScale;
        Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
        }

        /**
         * Prepare for a new round of painting. Since the component
         * may be resized, compute the scaling factor again.
         */
        public void preparePaint()
        {
            if(! size.equals(getSize())) {  // if the size has changed...
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;
                if(xScale < 1) {
                    xScale = GRID_VIEW_SCALING_FACTOR;
                }
                yScale = size.height / gridHeight;
                if(yScale < 1) {
                    yScale = GRID_VIEW_SCALING_FACTOR;
                }
            }
        }

        /**
         * Paint on grid location on this field in a given color.
         */
        public void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
        }

        /**
         * The field view component needs to be redisplayed. Copy the
         * internal image to screen.
         */
        public void paintComponent(Graphics g)
        {
            if(fieldImage != null) {
                Dimension currentSize = getSize();
                if(size.equals(currentSize)) {
