 11	    // Characteristics shared by all Liones (class variables).
 12	    
 13	    // The age at which a Lion can start to breed.
 14	    private static final int BREEDING_AGE = 10;
 15	    // The age to which a Lion can live.
 16	    private static final int MAX_AGE = 225;
