 18	    private static final double BREEDING_PROBABILITY = 0.10;
 19	    // The maximum number of births.
 20	    private static final int MAX_LITTER_SIZE = 5;
 21	    // The food value of a single lion.
 22	    private static final int FOOD_VALUE = 20;
 23	    // number of steps a lion can go before it has to eat again.
 24	    private static final int DEFAULT_FOOD_LEVEL = 275;
 25	    // The starting food level for newborn lions.
 26	    private static final int NEWBORN_FOOD_LEVEL = 40;
 27	
 28	    /**
 29	     * Create a Lion. A Lion can be created as a new born (age zero
 30	     * and not hungry) or with a random age and food level.
 31	     * 
 32	     * @param randomAge If true, the Lion will have random age and hunger level.
 33	     * @param field The field currently occupied.
 34	     * @param location The location within the field.
 35	     */
 36	    public Lion(boolean randomAge, Field field, Location location)
 37	    {
 38	        super(field, location);
 39	        initializeAge(randomAge, MAX_AGE);
 40	        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, NEWBORN_FOOD_LEVEL);
 41	    }
 42	    
 43	    /**
 44	     * This is what the Lion does most of the time: it hunts for
 45	     * rabbits. In the process, it might breed, die of hunger,
 46	     * or die of old age.
 47	     * If the weather is foggy, it stops moving.
 48	     * @param newLiones A list to return newly born Liones.
 49	     * @param step The current step.
 50	     * @param weather The current weather.
 51	     */
 52	    public void act(List<Animal> newLions, int step, Weather weather)
 53	    {
 54	        incrementAge(MAX_AGE);
 55	        decrementFoodLevel();
 56	        updateBurnStatus(weather);
 57	
 58	        if(isAlive()) {
 59	            giveBirth(newLions);            
 60	            // Move towards a source of food if found.
 61	            Location newLocation;
 62	            if (weather == Weather.FOGGY) {
 63	                newLocation = null;
 64	            }
 65	            else {
 66	                newLocation = findFood();
 67	            }
 68	            if(newLocation == null) { 
 69	                // No food found - try to move to a free location.
 70	                newLocation = freeAdjacentLocation();
 71	            }
 72	            // See if it was possible to move.
 73	            if (!TimeOfDay.fromStep(step).isNight()) {
 74	                moveToOrDie(newLocation);
 75	            } 
 76	        }
 77	    }
