 81	     * Only the first live deer/cat/owl/mouse is eaten.
 82	     * @return Where food was found, or null if it wasn't.
 83	     */
 84	    private Location findFood()
 85	    {
 86	        Location preyLocation = eat(Deer.class);
 87	        if(preyLocation != null) {
 88	            return preyLocation;
 89	        }
 90	
 91	        preyLocation = eat(Cat.class);
 92	        if(preyLocation != null) {
 93	            return preyLocation;
 94	        }
 95	
 96	        preyLocation = eat(Owl.class);
 97	        if(preyLocation != null) {
 98	            return preyLocation;
 99	        }
100	
101	        return eat(Mouse.class);
102	    }
103	    
104	    /**
105	     * Check whether or not this Lion is to give birth at this step.
106	     * New births will be made into free adjacent locations of the 24 nearest locations
107	     * surrounding the Lion.
108	     * @param newLions A list to return newly born Lions.
109	     */
110	    private void giveBirth(List<Animal> newLions)
111	    {
112	        if(hasAdjacentMate(Lion.class, 2)) {
113	            addOffspring(newLions, breed(), (field, location) -> new Lion(false, field, location));
114	        }
115	    }
116	        
117	    /**
118	     * Generate a number representing the number of births,
119	     * if it can breed.
120	     * @return The number of births (may be zero).
121	     */
122	    private int breed()
123	    {
124	        return calculateBirths(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
125	    }
126	
127	    /**
128	     * Hunt a specific prey species adjacent to this lion.
129	     */
130	    private <T extends Animal> Location eat(Class<T> preyClass)
131	    {
132	        return findAdjacentLocation(preyClass, 1, prey -> {
133	            if(prey.isAlive()) {
134	                prey.setDead();
135	                changeFoodLevel(prey.foodValue());
136	                return true;
137	            }
138	            return false;
139	        });
140	    }
