244	    protected final boolean hasAdjacentMate(Class<? extends Animal> animalClass, int radius)
245	    {
246	        for(Location where : adjacentLocations(radius)) {
247	            Object animal = getField().getObjectAt(where);
248	            if(animalClass.isInstance(animal)) {
249	                Animal mate = (Animal) animal;
250	                if(mate.getGender() != getGender()) {
251	                    return true;
252	                }
253	            }
254	        }
255	        return false;
